do $$ declare v_set uuid; begin select id into v_set from public.criteria_sets where code='BYT-83TC'; if v_set is null then return; end if; if exists (select 1 from public.assessment_rounds ar join public.criteria_set_versions cv on cv.id=ar.criteria_version_id where cv.criteria_set_id=v_set) then raise exception 'Duplicate set has assessment history; refusing delete'; end if; if exists (select 1 from public.criterion_responsibilities cr join public.criteria_set_versions cv on cv.id=cr.criteria_version_id where cv.criteria_set_id=v_set) then raise exception 'Duplicate set has responsibility history; refusing delete'; end if; delete from public.criteria_items where criteria_version_id in (select id from public.criteria_set_versions where criteria_set_id=v_set); delete from public.criteria_set_versions where criteria_set_id=v_set; delete from public.criteria_sets where id=v_set; end $$;
